export function localizeWorkbenchDynamicText(
  area: 'videoEdit' | 'creatorAgent' | 'inspiration',
  value: string,
): string {
  if (area === 'inspiration') return localizeInspirationDynamicText(value);
  const phraseCatalog = area === 'videoEdit' ? VIDEO_EDIT_VISIBLE_CATALOG : CREATOR_AGENT_VISIBLE_CATALOG;
  const phrase = (source: string) => phraseCatalog.englishByChinese[source] || source;
  const rules: Array<[RegExp, (...groups: string[]) => string]> = area === 'videoEdit'
    ? [
      [/^(\d+) 段$/, (count) => `${count} clips`],
      [/^超出 (.+)$/, (duration) => `Over by ${duration}`],
      [/^还差 (.+)$/, (duration) => `Remaining ${duration}`],
      [/^(\d+) 个阻塞$/, (count) => `${count} blockers`],
      [/^(\d+) 个提醒$/, (count) => `${count} warnings`],
      [/^(\d+) 段 · 总时长 (.+) · 体检 (.+) · 轻量拼接 \/ 裁短 \/ 转场 \/ 滤镜$/, (count, duration, health) => `${count} clips · total ${duration} · health ${phrase(health)} · lightweight join / trim / transitions / filters`],
      [/^第 (\d+) 页 \/ 共 (\d+) 页$/, (page, total) => `Page ${page} of ${total}`],
      [/^已选 (\d+) 项$/, (count) => `${count} selected`],
      [/^拆分(.+)$/, (kind) => `Split ${phrase(kind)}`],
      [/^复制(.+)$/, (kind) => `Duplicate ${phrase(kind)}`],
      [/^删除(.+)$/, (kind) => `Delete ${phrase(kind)}`],
      [/^主轨 (\d+)-(\d+)\/(\d+)$/, (start, end, total) => `Main track ${start}-${end}/${total}`],
      [/^主轨暂无 \/ 全轨 (\d+)$/, (total) => `Main track empty / all tracks ${total}`],
      [/^显示 (\d+)-(\d+)\/(\d+)$/, (start, end, total) => `Showing ${start}-${end}/${total}`],
      [/^无匹配 \/ 共 (\d+) 段$/, (total) => `No matches / ${total} clips total`],
      [/^多轨 (\d+)轨$/, (count) => `${count} tracks`], [/^PIP (\d+)轨$/, (count) => `${count} PIP tracks`],
      [/^PIP 当前 (\d+)\/(\d+)$/, (active, total) => `PIP active ${active}/${total}`],
      [/^字幕当前 (\d+)\/(\d+)$/, (active, total) => `Subtitles active ${active}/${total}`],
      [/^原声静音 0\/(\d+)$/, (total) => `Source audio muted 0/${total}`],
      [/^原声当前 (\d+)\/(\d+)$/, (active, total) => `Source audio active ${active}/${total}`],
      [/^音频当前 (\d+)\/(\d+) · (.+)$/, (active, total, status) => `Audio active ${active}/${total} · ${phrase(status)}`],
      [/^(\d+) 轨合成$/, (count) => `${count}-track composite`], [/^(\d+) 层$/, (count) => `${count} layers`], [/^(\d+) 条$/, (count) => `${count} items`],
      [/^(\d+) 层导出$/, (count) => `${count} layers exported`], [/^(\d+) 条烧录$/, (count) => `${count} burned in`], [/^(\d+) 条混合$/, (count) => `${count} mixed`],
      [/^(\d+) 项$/, (count) => `${count} items`], [/^多选 (\d+) 项$/, (count) => `${count} selected`],
      [/^过渡时长 (.+)$/, (duration) => `Transition duration ${duration}`], [/^节点 (.+)$/, (node) => `Node ${node}`],
      [/^转场切点 (\d+)：(.+) · (.+)$/, (index, label, duration) => `Transition cut ${index}: ${phrase(label)} · ${duration}`],
      [/^转场切点 (\d+)：(.+)，(.+)$/, (index, label, duration) => `Transition cut ${index}: ${phrase(label)}, ${duration}`],
      [/^叠加轨 (\d+) · (.+)$/, (index, name) => `Overlay track ${index} · ${name}`],
      [/^字幕 (.+)$/, (text) => `Subtitle ${text}`], [/^已设置 (.+)$/, (time) => `Set at ${time}`],
      [/^选择片段 (\d+) (.+)$/, (index, name) => `Select clip ${index} ${name}`],
      [/^片段可用于合成 · (.+)$/, (duration) => `Clip is ready to compose · ${duration}`],
      [/^拖动调整片段 (\d+) 入点$/, (index) => `Drag to adjust clip ${index} in point`], [/^拖动调整片段 (\d+) 出点$/, (index) => `Drag to adjust clip ${index} out point`],
    ]
    : [
      [/^(\d+) 个$/, (count) => `${count}`],
      [/^已引用 (\d+)$/, (count) => `${count} referenced`],
      [/^已固定 (\d+) 项$/, (count) => `${count} pinned`],
      [/^当前状态：(.+)$/, (status) => `Current status: ${phrase(status)}`],
      [/^(\d+) 个本机会话$/, (count) => `${count} local sessions`],
      [/^有 (\d+) 个待确认请求，请核对 Codex 与弹窗中的验证码。$/, (count) => `${count} pending request(s). Verify the code shown in Codex and the dialog.`],
      [/^模型调用 (\d+) 次$/, (count) => `${count} model calls`], [/^(\d+) 项变更已核对，尚未写入画布$/, (count) => `${count} changes verified; nothing has been written to the canvas.`],
      [/^(\d+) 项建议已准备，尚未执行$/, (count) => `${count} suggestion(s) ready; not executed`],
      [/^无法准备这条操作预览：(.+)$/, (reason) => `Could not prepare this operation preview: ${reason}`],
      [/^画布已更新到 r(\d+)；没有自动运行生成节点$/, (revision) => `Canvas updated to r${revision}; generation nodes were not run automatically.`],
      [/^画布已精确恢复并更新到 r(\d+)$/, (revision) => `Canvas precisely restored and updated to r${revision}`],
      [/^(.+)已完成$/, (subject) => `${phrase(subject)} completed`], [/^(.+)未完成$/, (subject) => `${phrase(subject)} incomplete`],
      [/^(.+)进行中(?: · (\d+)%)?$/, (subject, progress) => `${phrase(subject)} in progress${progress ? ` · ${progress}%` : ''}`],
      [/^(\d+) 个已核验素材 · (.+)；确认前不会创建任何文件$/, (count, size) => `${count} verified assets · ${size}; no files are created before confirmation.`],
      [/^(\d+) 个 NodeRun$/, (count) => `${count} NodeRuns`], [/^(\d+) 次 Attempt$/, (count) => `${count} Attempts`], [/^(\d+) 个产物引用$/, (count) => `${count} output references`],
      [/^另有 (\d+) 个资产索引$/, (count) => `${count} more asset indexes`], [/^(\d+) 秒$/, (seconds) => `${seconds} sec`], [/^(\d+) 镜头$/, (count) => `${count} shots`], [/^(\d+) 资产$/, (count) => `${count} assets`],
      [/^已检查 (\d+)\/(\d+)$/, (done, total) => `Reviewed ${done}/${total}`], [/^(\d+) 个候选$/, (count) => `${count} candidates`],
      [/^当前创作会话已验证 · 计划 (.+)$/, (plan) => `Current creation session verified · plan ${plan}`],
      [/^物理产物已核验 · (\d+) 项 · SHA-256 \/ 魔数 \/ 运行关联$/, (count) => `Physical outputs verified · ${count} items · SHA-256 / magic bytes / run linkage`],
      [/^物理产物未通过 · (.+)$/, (reason) => `Physical output verification failed · ${phrase(reason)}`],
      [/^受众：(.+)$/, (content) => `Audience: ${content}`], [/^形式：(.+)$/, (content) => `Format: ${content}`], [/^画幅：(.+)$/, (content) => `Aspect ratio: ${content}`],
      [/^时长：(.+) 秒$/, (content) => `Duration: ${content} sec`], [/^风格：(.+)$/, (content) => `Style: ${content}`], [/^视觉：(.+)$/, (content) => `Visuals: ${content}`],
      [/^已绑定视频：(.+)$/, (name) => `Bound video: ${name}`], [/^素材版本 r(.+)$/, (revision) => `Asset revision r${revision}`], [/^已安全回收 (\d+) 个镜头$/, (count) => `${count} shots safely recovered`],
      [/^(\d+) 项拉片维度$/, (count) => `${count} breakdown dimensions`], [/^连续性锁定 (\d+) 项$/, (count) => `${count} continuity locks`],
      [/^角色来源 · (\d+) 项$/, (count) => `Character sources · ${count}`], [/^资产缺口 · (\d+) 项$/, (count) => `Asset gaps · ${count}`], [/^镜头表 · (\d+) 镜$/, (count) => `Shot list · ${count}`],
      [/^AudioPlan · (\d+) 条$/, (count) => `AudioPlan · ${count}`], [/^分镜板 · (\d+) 格$/, (count) => `Storyboard · ${count}`], [/^PromptPack · (\d+) 条$/, (count) => `PromptPack · ${count}`],
      [/^已完成 (\d+)\/(\d+) 个阶段；每次前进或返修都会保存在当前作品会话。$/, (done, total) => `${done}/${total} phases completed. Every advance or revision is saved in this work session.`],
      [/^当前停在「(.+)」$/, (phase) => `Currently stopped at “${phrase(phase)}”`], [/^正在返修「(.+)」$/, (phase) => `Revising “${phrase(phase)}”`], [/^当前在「(.+)」$/, (phase) => `Current phase: “${phrase(phase)}”`],
      [/^(.+)需要重新确认$/, (phase) => `${phrase(phase)} needs reconfirmation`], [/^(\d+) 项版本差异$/, (count) => `${count} version changes`], [/^(\d+) 项来源已核对$/, (count) => `${count} sources verified`],
      [/^已就绪 (\d+)\/(\d+) 个模型 · (\d+)\/(\d+) 个专项动作$/, (models, modelTotal, actions, actionTotal) => `${models}/${modelTotal} models ready · ${actions}/${actionTotal} specialized actions`],
      [/^(打开|关闭)贞贞创作 Agent；当前状态：(.+)；装饰特效(已开启|已关闭)$/, (action, status, effects) => `${phrase(action)} Zhenzhen Creator Agent; current status: ${phrase(status)}; decorative effects ${phrase(effects).toLowerCase()}`],
      [/^AI 创作助手 · (.+)$/, (status) => `AI creation assistant · ${phrase(status)}`],
      [/^Codex 已安全连接 · (\d+) 个本机会话$/, (count) => `Codex securely connected · ${count} local sessions`],
      [/^当前权限：(.+)$/, (scopes) => `Current permissions: ${scopes}`], [/^(\d+) 条来源$/, (count) => `${count} lineage events`],
    ];
  for (const [pattern, render] of rules) {
    const match = value.match(pattern);
    if (match) return render(...match.slice(1));
  }
  return value;
}
